def quote(subtotal, member):
    if member:
        if subtotal >= 50:
            return {"subtotal": subtotal, "delivery": 0, "total": subtotal}
        return {"subtotal": subtotal, "delivery": 3, "total": subtotal + 3}
    if subtotal >= 50:
        return {"subtotal": subtotal, "delivery": 0, "total": subtotal}
    return {"subtotal": subtotal, "delivery": 5, "total": subtotal + 5}

import unittest
from shipping import quote

class QuoteTests(unittest.TestCase):
    def test_regular_below(self):
        self.assertEqual({"subtotal": 49, "delivery": 5, "total": 54}, quote(49, False))
    def test_member_below(self):
        self.assertEqual({"subtotal": 49, "delivery": 3, "total": 52}, quote(49, True))
    def test_regular_threshold(self):
        self.assertEqual({"subtotal": 50, "delivery": 0, "total": 50}, quote(50, False))
    def test_member_threshold(self):
        self.assertEqual({"subtotal": 50, "delivery": 0, "total": 50}, quote(50, True))

if __name__ == "__main__":
    unittest.main()
